class OrderError(Exception):
    """Base for all order problems."""

class InvalidOrderError(OrderError):
    def __init__(self, field: str, message: str):
        super().__init__(message)
        self.field = field

def parse_order(text: str) -> tuple[str, int]:
    sku, _, qty_text = text.partition(", qty=")
    try:
        qty = int(qty_text)
    except ValueError as err:
        raise InvalidOrderError("quantity", "quantity must be a whole number") from err
    return sku, qty
```

| Callers can… | Using |
|---|---|
| catch any order problem. | `except OrderError`. |
| highlight the bad field. | `err.field`. |
| debug the root cause. | `err.__cause__` (the ValueError). |

